from sympy import symbols, solve, simplify

def solve_case(x1, x2, x3, v1, v2, v3):
    a, b, c = symbols('a b c', real=True)
    eqs = [a * x1 ** 2 + b * x1 + c - v1, a * x2 ** 2 + b * x2 + c - v2, a * x3 ** 2 + b * x3 + c - v3]
    sol = solve(eqs, (a, b, c))
    if sol:
        res = sol[0]
        f_x = res[0] * symbols('x') ** 2 + res[1] * symbols('x') + res[2]
        vertex = -res[1] / (2 * res[0]) if res[0] != 0 else None
        test_points = [0, 1]
        if vertex is not None and 0 < vertex < 1:
            test_points.append(vertex)
        valid = True
        for tp in test_points:
            val = res[0] * tp ** 2 + res[1] * tp + res[2]
            if abs(val) > 1.0000000001:
                valid = False
                break
        if valid:
            return abs(res[0]) + abs(res[1]) + abs(res[2])
    return 0
